1	package custody
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// 销毁前数量守恒核对的测试。
13	//
14	// 背景：重新打开旧文件时，未销毁样品允许“剩余量 + 直接分出总量 < 自身
15	// 初始量”（差额作为旧记录保留，可打开、可查询）；但销毁会写下重新打开
16	// 时必须恰好守恒的销毁记录，因此销毁前必须先核对同一等式，数量有缺口
17	// 就明确返回 ErrConflict，不能销毁成功后让文件再也无法打开。
18	//
19	// 这些缺口状态无法通过公开的登记/分装操作产生（分装总是精确扣减），
20	// 因此沿用 writeStructLedger 构造旧文件，先证明它能按旧约定打开，再
21	// 通过公开的 Destroy 验证拒绝行为。
22	
23	// openGapLedger 写入构造数据并按旧约定打开；打开本身必须成功，否则
24	// 后续的销毁拒绝测试没有意义。
25	func openGapLedger(t *testing.T, l *ledger) (*Store, string) {
26		t.Helper()
27		path := writeStructLedger(t, l)
28		s, err := Open(path)
29		if err != nil {
30			t.Fatalf("前置条件：有缺口的未销毁旧记录必须能打开: %v", err)
31		}
32		return s, path
33	}
34	
35	// destroyGapAt 晚于构造数据中的登记/分装历史，用于发起销毁请求。
36	var destroyGapAt = time.Date(2026, 10, 4, 12, 0, 0, 0, time.UTC)
37	
38	// assertStillOpenAndUndestroyed 在销毁被拒绝后重新打开同一文件，确认旧
39	// 记录仍可打开、查询，且仍是未销毁、数量与子样关系保持原样。
40	func assertStillOpenAndUndestroyed(t *testing.T, path, id, remaining string, children []string) {
41		t.Helper()
42		s2, err := Open(path)
43		if err != nil {
44			t.Fatalf("被拒绝销毁的旧文件必须仍能重新打开: %v", err)
45		}
46		got, err := s2.GetSample(id)
47		if err != nil {
48			t.Fatalf("重新打开后旧记录必须仍可查询: %v", err)
49		}
50		if got.Destruction != nil {
51			t.Fatalf("拒绝销毁后不得留下销毁记录: %+v", got.Destruction)
52		}
53		if got.Remaining != remaining {
54			t.Fatalf("剩余量应保持 %s, got %s", remaining, got.Remaining)
55		}
56		if len(got.Children) != len(children) {
57			t.Fatalf("子样列表被改动: got %v want %v", got.Children, children)
58		}
59		for i, c := range children {
60			if got.Children[i] != c {
61				t.Fatalf("子样列表被改动: got %v want %v", got.Children, children)
62			}
63		}
64	}
65	
66	// TestDestroyRejectsTaskExampleGap 任务示例：原样初始 10.000，直接子样
67	// 创建时取得 4.000，原样却只剩 5.000（旧记录 5.000+4.000=9.000 <
68	// 10.000，仍可打开）。销毁必须被拒绝：返回 nil 结果与 ErrConflict，
69	// 错误说明写明样品编号并以三位小数毫升列出初始量 10.000、剩余量
70	// 5.000、直接分出总量 4.000 和缺口 1.000；样品仍为未销毁，文件原样
71	// 保留，之后同一文件仍能打开并查询。
72	func TestDestroyRejectsTaskExampleGap(t *testing.T) {
73		l := &ledger{
74			Samples: map[string]*sampleRecord{
75				"S-001":   withChild(activeSample("S-001", "", 10000, 5000), "S-001-A"),
76				"S-001-A": plainChild("S-001-A", "S-001", 4000, 4000),
77			},
78		}
79		s, path := openGapLedger(t, l)
80	
81		before, _ := s.GetSample("S-001")
82		rawBefore, err := os.ReadFile(path)
83		if err != nil {
84			t.Fatal(err)
85		}
86	
87		got, err := s.Destroy(DestroyInput{
88			SampleID: "S-001", Operator: "h", Location: "l",
89			At: destroyGapAt, Reason: "实验结束按规程销毁",
90		})
91		if err == nil {
92			t.Fatalf("数量有缺口时销毁必须被拒绝，却返回了成功结果: %+v", got)
93		}
94		if got != nil {
95			t.Fatalf("销毁被拒绝时不得返回样品结果, got %+v", got)
96		}
97		if !errors.Is(err, ErrConflict) {
98			t.Fatalf("缺口拒绝应可用 errors.Is 判定为 ErrConflict, got %v", err)
99		}
