247		childExhausted.Children = []string{"G"}
248		childExhausted.History = append(childExhausted.History, historyRecord{
249			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
250		})
251		good1 := &ledger{
252			Samples: map[string]*sampleRecord{
253				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
254				"C": childExhausted,
255				"G": plainChild("G", "C", 4000, 4000),
256			},
257		}
258		s1, path1 := openGapLedger(t, good1)
259		view, err := s1.Destroy(DestroyInput{
260			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
261		})
262		if err != nil {
263			t.Fatalf("孙样不重复计入，6.000+4.000=10.000 应销毁成功: %v", err)
