235				"P":   withChild(activeSample("P", "", 10000, 6000), "C"),
236				"C":   withChild(plainChild("C", "P", 4000, 0), "G"),
237				"G":   plainChild("G", "C", 4000, 4000),
238				"R":   withChild(activeSample("R", "", 8000, 1000), "R-D"),
239				"R-D": plainChild("R-D", "R", 7000, 7000),
240			},
241		}
