185			}
186		}
187		if tc, _ := s.GetTransfer("TC"); tc.Qty != "3.250" {
188			t.Fatalf("子样交接量应原样恢复为 3.250, got %s", tc.Qty)
189		}
190	}
191	
192	// TestOpenKeepsHistoricalConfirmedQuantitiesRegardlessOfLaterChanges 旧交接
193	// 的上限不是样品当前剩余量，多次转手量也不能相加后与初始量比较：原样先
194	// 以 10.000 完成交接，之后分出 3.250 子样、再以剩余的 6.750 完成第二次
195	// 交接；两条已确认交接（合计 16.750 > 初始 10.000）都必须按当时的数量
196	// 原样保留。样品后来换了持有人、地点也同样不影响恢复与查询。
197	func TestOpenKeepsHistoricalConfirmedQuantitiesRegardlessOfLaterChanges(t *testing.T) {
198		holder := "王五"
199		location := "实验室C"
200		parent := activeSample("S-001", "", 10000, 6750)
201		parent.Holder = holder
202		parent.Location = location
