215		second.HandedOverAt = hAt2
216		second.ReceivedAt = &rAt2
217		second.ConfirmedBy = holder
218	
219		l := &ledger{
220			Samples: map[string]*sampleRecord{
221				"S-001":   parent,
222				"S-001-A": child,
223			},
224			Transfers: map[string]*transferRecord{
225				"TR-001": confirmedTransferRecord("TR-001", "S-001", 10000),
226				"TR-002": second,
227			},
228		}
229		s, err := Open(writeStructLedger(t, l))
230		if err != nil {
231			t.Fatalf("两条历史已确认交接都不超过各自发生时样品自身初始量，应正常恢复: %v", err)
232		}
233		first, err := s.GetTransfer("TR-001")
234		if err != nil {
235			t.Fatal(err)
236		}
237		if !first.Confirmed || first.Qty != "10.000" {
238			t.Fatalf("第一次旧交接必须保留当时的 10.000 毫升: %+v", first)
239		}
240		next, err := s.GetTransfer("TR-002")
241		if err != nil {
242			t.Fatal(err)
243		}
244		if !next.Confirmed || next.Qty != "6.750" || next.ConfirmedBy != "王五" {
245			t.Fatalf("第二次交接必须保留当时的 6.750 毫升与接收事实: %+v", next)
246		}
