1	package custody
2	
3	import (
4		"errors"
5		"path/filepath"
6		"testing"
7		"time"
8	)
9	
10	// fixedNow 让事件时间在测试中确定。
11	func fixedStore(t *testing.T) (*Store, time.Time) {
12		t.Helper()
13		dir := t.TempDir()
14		clock := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
15		s, err := Open(filepath.Join(dir, "data.json"))
16		if err != nil {
17			t.Fatalf("open: %v", err)
18		}
19		s.now = func() time.Time { return clock }
20		return s, clock
21	}
22	
23	func mustRegister(t *testing.T, s *Store, id, qty, holder, loc string) *Sample {
24		t.Helper()
25		got, err := s.Register(RegisterInput{ID: id, Qty: qty, Holder: holder, Location: loc})
26		if err != nil {
27			t.Fatalf("register %s: %v", id, err)
28		}
29		return got
30	}
31	
32	func TestRegisterAndQuery(t *testing.T) {
33		s, now := fixedStore(t)
34	
35		got := mustRegister(t, s, " S-001 ", "10.5", " 张三 ", " 实验室A ")
36		if got.ID != "S-001" || got.Holder != "张三" || got.Location != "实验室A" {
37			t.Fatalf("登记后字段未去空白: %+v", got)
38		}
39		if got.InitialQty != "10.500" || got.Remaining != "10.500" {
40			t.Fatalf("数量应统一显示三位小数, got init=%s rem=%s", got.InitialQty, got.Remaining)
41		}
42		if got.ParentID != "" || len(got.Children) != 0 {
43			t.Fatalf("原样不应有来源或子样: %+v", got)
44		}
45		if len(got.History) != 1 || got.History[0].Kind != "register" ||
46			!got.History[0].Time.Equal(now) || got.History[0].Holder != "张三" {
47			t.Fatalf("登记历史不正确: %+v", got.History)
48		}
49		if got.PendingTransfer != nil {
50			t.Fatalf("新登记样品不应有待确认交接")
51		}
52	}
53	
54	func TestRegisterValidation(t *testing.T) {
55		s, _ := fixedStore(t)
56		mustRegister(t, s, "S1", "1", "h", "l")
57	
58		cases := []struct {
59			name string
60			in   RegisterInput
61			want error
62		}{
63			{"空白编号", RegisterInput{ID: "   ", Qty: "1", Holder: "h", Location: "l"}, ErrInvalid},
64			{"空白持有人", RegisterInput{ID: "S2", Qty: "1", Holder: " ", Location: "l"}, ErrInvalid},
65			{"空白地点", RegisterInput{ID: "S2", Qty: "1", Holder: "h", Location: ""}, ErrInvalid},
66			{"零数量", RegisterInput{ID: "S2", Qty: "0", Holder: "h", Location: "l"}, ErrInvalid},
67			{"负数量", RegisterInput{ID: "S2", Qty: "-1", Holder: "h", Location: "l"}, ErrInvalid},
68			{"四位小数", RegisterInput{ID: "S2", Qty: "1.0001", Holder: "h", Location: "l"}, ErrInvalid},
69			{"非数字", RegisterInput{ID: "S2", Qty: "abc", Holder: "h", Location: "l"}, ErrInvalid},
70			{"科学计数", RegisterInput{ID: "S2", Qty: "1e3", Holder: "h", Location: "l"}, ErrInvalid},
71			{"点开头", RegisterInput{ID: "S2", Qty: ".5", Holder: "h", Location: "l"}, ErrInvalid},
72			{"重复编号", RegisterInput{ID: "S1", Qty: "1", Holder: "h", Location: "l"}, ErrConflict},
73		}
74		for _, c := range cases {
75			t.Run(c.name, func(t *testing.T) {
76				if _, err := s.Register(c.in); !errors.Is(err, c.want) {
77					t.Fatalf("want %v, got %v", c.want, err)
78				}
79			})
80		}
81	
82		// 被拒绝的登记不得顺带创建记录。
83		if _, err := s.GetSample("S2"); !errors.Is(err, ErrNotFound) {
84			t.Fatalf("失败的登记不应创建样品, got %v", err)
85		}
86	}
87	
88	func TestQuantityBoundary(t *testing.T) {
89		s, _ := fixedStore(t)
90		// 0.001 是最小合法数量；三位小数可精确分装不丢失。
91		mustRegister(t, s, "T", "0.001", "h", "l")
92		got, err := s.GetSample("T")
93		if err != nil {
94			t.Fatal(err)
95		}
96		if got.InitialQty != "0.001" {
97			t.Fatalf("got %s", got.InitialQty)
98		}
99	}
100	
101	func TestSplitSuccessAndChaining(t *testing.T) {
102		s, _ := fixedStore(t)
103		mustRegister(t, s, "P", "10.000", "张三", "实验室A")
104	
105		parent, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
106			{ID: "C1", Qty: "3.333"},
107			{ID: "C2", Qty: "6.667"},
108		}})
109		if err != nil {
110			t.Fatalf("split: %v", err)
111		}
112		// 整数刻度精确守恒：3.333 + 6.667 = 10.000，剩余正好为 0。
113		if parent.Remaining != "0.000" {
114			t.Fatalf("分装后剩余应为 0.000, got %s", parent.Remaining)
115		}
116		if len(parent.Children) != 2 || parent.Children[0] != "C1" || parent.Children[1] != "C2" {
117			t.Fatalf("子样顺序不正确: %v", parent.Children)
118		}
119	
120		for _, id := range []string{"C1", "C2"} {
121			c, err := s.GetSample(id)
122			if err != nil {
123				t.Fatal(err)
124			}
125			if c.ParentID != "P" || c.Holder != "张三" || c.Location != "实验室A" {
126				t.Fatalf("子样 %s 未正确继承: %+v", id, c)
127			}
128		}
129	
130		// 子样可以继续分装。
131		c1, err := s.GetSample("C1")
132		if err != nil {
133			t.Fatal(err)
134		}
135		if _, err := s.Split(SplitInput{ParentID: "C1", Parts: []SplitPart{
