1	package custody
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 销毁数量恢复核对相关测试。
14	//
15	// 规则：带销毁信息的样品恢复时，当前剩余量必须为 0.000，自身初始量与
16	// 实际销毁量都大于零，且实际销毁量加上各直接子样创建时取得的初始量之和
17	// 恰好等于该样品自身的初始量。子样后来的分装、转交、销毁都不改变原样
18	// 当时已分出的量，孙样不重复计入。
19	
20	// destroyedAt 为销毁类构造数据使用的固定时间。
21	var destroyedCheckAt = time.Date(2026, 10, 3, 12, 0, 0, 0, time.UTC)
22	
23	// registerHistoryAt / splitHistoryAt 为构造数据中的既有历史时间。
24	var (
25		registerCheckAt = time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
26		splitCheckAt    = time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
27	)
28	
29	// writeStructLedger 把内存 ledger 结构序列化为临时数据文件并返回路径，
30	// 便于构造公开操作无法产生的各种数量组合。
31	func writeStructLedger(t *testing.T, l *ledger) string {
32		t.Helper()
33		if l.Version == 0 {
34			l.Version = 1
35		}
36		if l.Samples == nil {
37			l.Samples = map[string]*sampleRecord{}
38		}
39		if l.Transfers == nil {
40			l.Transfers = map[string]*transferRecord{}
41		}
42		raw, err := json.MarshalIndent(l, "", "  ")
43		if err != nil {
44			t.Fatalf("序列化测试数据: %v", err)
45		}
46		return writeRawLedger(t, string(raw))
47	}
48	
49	// destroyedSample 构造一份带销毁信息的样品记录，数量单位均为千分之一毫升。
50	func destroyedSample(id string, initial, remaining, destroyedQty int64, children ...string) *sampleRecord {
51		s := &sampleRecord{
52			ID:        id,
53			Initial:   initial,
54			Remaining: remaining,
55			Holder:    "李四",
56			Location:  "实验室B",
57			Children:  append([]string{}, children...),
58			History: []historyRecord{{
59				Kind: "register", Time: registerCheckAt, Holder: "李四", Location: "实验室B",
60			}},
61			Destroyed: &destructionRecord{
62				Operator: "李四",
63				Location: "实验室B",
64				At:       destroyedCheckAt,
65				Reason:   "实验结束按规程销毁",
66				Qty:      destroyedQty,
67			},
68		}
69		if len(children) > 0 {
70			s.History = append(s.History, historyRecord{
71				Kind: "split", Time: splitCheckAt, Holder: "李四", Location: "实验室B",
72			})
73		}
74		s.History = append(s.History, historyRecord{
75			Kind: "destroy", Time: destroyedCheckAt, Holder: "李四", Location: "实验室B",
76		})
77		return s
78	}
79	
80	// plainChild 构造一份未销毁子样记录。
81	func plainChild(id, parent string, initial, remaining int64) *sampleRecord {
82		return &sampleRecord{
83			ID:        id,
84			ParentID:  parent,
85			Initial:   initial,
86			Remaining: remaining,
87			Holder:    "李四",
88			Location:  "实验室B",
89			Children:  []string{},
90			History: []historyRecord{{
91				Kind: "split", Time: splitCheckAt, Holder: "李四", Location: "实验室B",
92			}},
93		}
94	}
95	
96	// TestOpenRejectsDestroyedFullInitialAfterSplit 任务示例：原样初始
97	// 10.000、已分出 3.250 子样，正确销毁量应是 6.750；文件却把销毁量写成
98	// 10.000（剩余量已归零、交接均合法），必须拒绝打开，不能把多出的量当作
99	// 真实销毁。错误信息写明样品编号、初始量、销毁量与直接子样总量。
100	func TestOpenRejectsDestroyedFullInitialAfterSplit(t *testing.T) {
101		l := &ledger{
102			Samples: map[string]*sampleRecord{
103				"S-001":   destroyedSample("S-001", 10000, 0, 10000, "S-001-A"),
104				"S-001-A": plainChild("S-001-A", "S-001", 3250, 3250),
105			},
106		}
107		path := writeStructLedger(t, l)
108		mustRejectOpen(t, path, "S-001", "10.000", "3.250", "销毁")
109	}
110	
111	// TestOpenRejectsDestroyedWithNonZeroRemaining 带销毁信息但剩余量未归零，
112	// 即使销毁量加子样量恰好等于初始量也拒绝。
113	func TestOpenRejectsDestroyedWithNonZeroRemaining(t *testing.T) {
114		l := &ledger{
115			Samples: map[string]*sampleRecord{
116				"S-001":   destroyedSample("S-001", 10000, 1000, 6750, "S-001-A"),
117				"S-001-A": plainChild("S-001-A", "S-001", 3250, 3250),
118			},
119		}
120		path := writeStructLedger(t, l)
121		mustRejectOpen(t, path, "S-001", "0.000", "1.000")
122	}
123	
124	// TestOpenRejectsNonPositiveQuantities 参与核对的初始量与实际销毁量都必须
125	// 大于零，零值与负值一律拒绝。
126	func TestOpenRejectsNonPositiveQuantities(t *testing.T) {
127		cases := []struct {
128			name      string
129			initial   int64
130			destroyed int64
131			mention   string
132		}{
133			{"销毁量为零", 1000, 0, "销毁量"},
134			{"销毁量为负", 1000, -1000, "销毁量"},
135			{"初始量为零", 0, 0, "初始量"},
136			{"初始量为负", -1000, -1000, "初始量"},
137		}
138		for _, c := range cases {
139			t.Run(c.name, func(t *testing.T) {
140				l := &ledger{
141					Samples: map[string]*sampleRecord{
142						"BAD": destroyedSample("BAD", c.initial, 0, c.destroyed),
143					},
144				}
145				path := writeStructLedger(t, l)
146				mustRejectOpen(t, path, "BAD", c.mention, "大于零")
147			})
148		}
149	}
150	
151	// TestOpenRejectsDestroyedMismatchWithoutChildren 没有分出子样的样品，
152	// 实际销毁量必须等于自身初始量；4.000 != 5.000 时拒绝，信息展示初始量
153	// 5.000、销毁量 4.000 与直接子样总量 0.000。
154	func TestOpenRejectsDestroyedMismatchWithoutChildren(t *testing.T) {
155		l := &ledger{
156			Samples: map[string]*sampleRecord{
157				"LEAF": destroyedSample("LEAF", 5000, 0, 4000),
158			},
159		}
160		path := writeStructLedger(t, l)
161		mustRejectOpen(t, path, "LEAF", "5.000", "4.000", "0.000")
162	}
163	
164	// TestOpenRejectsDestroyedWhenChildMissing Children 列着不存在的直接子样，
165	// 无法统计分出量，按损坏数据拒绝。
166	func TestOpenRejectsDestroyedWhenChildMissing(t *testing.T) {
167		l := &ledger{
168			Samples: map[string]*sampleRecord{
169				"S-001": destroyedSample("S-001", 10000, 0, 6750, "GHOST"),
170			},
171		}
172		path := writeStructLedger(t, l)
173		mustRejectOpen(t, path, "S-001", "GHOST")
174	}
175	
176	// TestOpenRejectsDestroyedDuplicateChildListing 任务示例：原样 P 初始
177	// 10.000，C 由 P 分出 3.000，P 销毁剩余 4.000；子样列表却把 C 写了两遍，
178	// 销毁量加两次 C 的合计碰巧等于初始量（4.000+3.000+3.000=10.000）。重复
179	// 列入使来源关系自相矛盾，必须拒绝，不能靠删除重复项接受文件。
180	func TestOpenRejectsDestroyedDuplicateChildListing(t *testing.T) {
181		l := &ledger{
182			Samples: map[string]*sampleRecord{
183				"P": destroyedSample("P", 10000, 0, 4000, "C", "C"),
184				"C": plainChild("C", "P", 3000, 3000),
185			},
186		}
187		path := writeStructLedger(t, l)
188		mustRejectOpen(t, path, "P", "C", "重复")
189	}
190	
191	// TestOpenRejectsDestroyedChildFromOtherRoot 列入的子样实际来自另一份原样，
192	// 即使销毁量 7.000 加该子样初始量 3.000 恰好等于初始量 10.000，来源不符
193	// 也必须拒绝，不能靠凑齐数量通过核对。
194	func TestOpenRejectsDestroyedChildFromOtherRoot(t *testing.T) {
195		l := &ledger{
196			Samples: map[string]*sampleRecord{
197				"P":  destroyedSample("P", 10000, 0, 7000, "C"),
198				"C":  plainChild("C", "P2", 3000, 3000),
199				"P2": plainChild("P2", "", 8000, 8000),
200			},
201		}
202		path := writeStructLedger(t, l)
203		mustRejectOpen(t, path, "P", "C", "P2", "来源")
204	}
205	
206	// TestOpenRejectsDestroyedChildWithoutParent 列入的编号其实是没有来源的
207	// 原样，不能当作本样品的直接子样凑数量。
208	func TestOpenRejectsDestroyedChildWithoutParent(t *testing.T) {
209		l := &ledger{
210			Samples: map[string]*sampleRecord{
211				"P": destroyedSample("P", 10000, 0, 7000, "R"),
212				"R": plainChild("R", "", 3000, 3000),
213			},
214		}
215		path := writeStructLedger(t, l)
216		mustRejectOpen(t, path, "P", "R", "来源")
217	}
218	
219	// TestOpenRejectsDestroyedMissingChildListing 反向核对：子样 C 的来源编号
220	// 指向 P，P 的子样列表却没有列 C。P 销毁量 10.000、空列表使数量等式
221	// 单独成立（10.000=10.000），漏列仍必须拒绝，不能忽略漏列项接受文件。
222	func TestOpenRejectsDestroyedMissingChildListing(t *testing.T) {
223		l := &ledger{
224			Samples: map[string]*sampleRecord{
225				"P": destroyedSample("P", 10000, 0, 10000),
226				"C": plainChild("C", "P", 3000, 3000),
227			},
228		}
229		path := writeStructLedger(t, l)
230		mustRejectOpen(t, path, "P", "C", "漏列")
231	}
232	
233	// TestOpenRejectsDestroyedSplitChildMissingGrandchild 关系核对同样适用于
234	// 已销毁的分装子样：C 已销毁且孙样 G 的来源指向 C，C 的子样列表漏列 G，
235	// 即使 C 的销毁量 3.000 与其自身初始量相等也必须拒绝。
236	func TestOpenRejectsDestroyedSplitChildMissingGrandchild(t *testing.T) {
237		l := &ledger{
238			Samples: map[string]*sampleRecord{
239				"P": plainChild("P", "", 7000, 7000),
240				"C": destroyedSampleWithParent("C", "P", 3000, 3000),
241				"G": plainChild("G", "C", 1000, 1000),
242			},
243		}
244		path := writeStructLedger(t, l)
245		mustRejectOpen(t, path, "C", "G", "漏列")
246	}
247	
248	// TestOpenRestoresDestroyedWithSingleDirectChild 任务示例的合法对照：P 初始
249	// 10.000、C 由 P 分出 3.000 且只列一次，P 销毁 7.000（7.000+3.000=
250	// 10.000），关系一致、数量守恒，正常恢复并保留子样顺序。
251	func TestOpenRestoresDestroyedWithSingleDirectChild(t *testing.T) {
252		l := &ledger{
253			Samples: map[string]*sampleRecord{
254				"P": destroyedSample("P", 10000, 0, 7000, "C"),
255				"C": plainChild("C", "P", 3000, 3000),
256			},
257		}
258		s, err := Open(writeStructLedger(t, l))
259		if err != nil {
260			t.Fatalf("C 只列一次且销毁量为 7.000 应符合记录、正常恢复: %v", err)
261		}
262		p, _ := s.GetSample("P")
263		if p.Destruction == nil || p.Destruction.Qty != "7.000" ||
264			len(p.Children) != 1 || p.Children[0] != "C" {
265			t.Fatalf("销毁量与子样列表应原样保留: %+v", p)
266		}
267	}
268	
269	// TestOpenRejectsDestroyedWhenChildInitialNotPositive 直接子样初始量必须
270	// 大于零，否则销毁数量核对无意义，拒绝恢复。
271	func TestOpenRejectsDestroyedWhenChildInitialNotPositive(t *testing.T) {
272		l := &ledger{
273			Samples: map[string]*sampleRecord{
274				"S-001":   destroyedSample("S-001", 10000, 0, 10000, "S-001-A"),
275				"S-001-A": plainChild("S-001-A", "S-001", 0, 0),
276			},
277		}
278		path := writeStructLedger(t, l)
279		mustRejectOpen(t, path, "S-001", "S-001-A", "大于零")
280	}
281	
282	// TestOpenRejectsDestroyedAccountingDespiteOtherValidSamples 一份销毁记录
283	// 不符时整份文件打开失败，不能只加载其他正常样品，也不改写原文件。
284	func TestOpenRejectsDestroyedAccountingDespiteOtherValidSamples(t *testing.T) {
285		l := &ledger{
286			Samples: map[string]*sampleRecord{
287				"OK":    destroyedSample("OK", 1000, 0, 1000),
288				"BAD":   destroyedSample("BAD", 10000, 0, 10000, "BAD-C"),
289				"BAD-C": plainChild("BAD-C", "BAD", 3250, 3250),
290			},
291		}
292		path := writeStructLedger(t, l)
293		mustRejectOpen(t, path, "BAD", "10.000", "3.250")
294	}
295	
296	// TestOpenRestoresDestroyedParentAfterSplit 合法分支：初始 10.000、分出
297	// 3.250 后销毁剩余 6.750，重开正常恢复；销毁记录、子样与数量均保留。
298	func TestOpenRestoresDestroyedParentAfterSplit(t *testing.T) {
299		l := &ledger{
300			Samples: map[string]*sampleRecord{
301				"S-001":   destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
302				"S-001-A": plainChild("S-001-A", "S-001", 3250, 3250),
303			},
304		}
305		path := writeStructLedger(t, l)
306		s, err := Open(path)
307		if err != nil {
308			t.Fatalf("销毁量 6.750 + 直接子样 3.250 = 初始 10.000 应正常恢复: %v", err)
309		}
310		p, err := s.GetSample("S-001")
311		if err != nil {
312			t.Fatal(err)
313		}
314		if p.InitialQty != "10.000" || p.Remaining != "0.000" {
315			t.Fatalf("父样数量错误: init=%s remaining=%s", p.InitialQty, p.Remaining)
316		}
317		if p.Destruction == nil || p.Destruction.Qty != "6.750" {
318			t.Fatalf("父样销毁量应恢复为 6.750: %+v", p.Destruction)
319		}
320		if len(p.Children) != 1 || p.Children[0] != "S-001-A" {
321			t.Fatalf("直接子样列表应保留: %v", p.Children)
322		}
323		c, err := s.GetSample("S-001-A")
324		if err != nil {
325			t.Fatal(err)
326		}
327		if c.InitialQty != "3.250" || c.Remaining != "3.250" || c.Destruction != nil {
328			t.Fatalf("子样不应被父样销毁核对改动: %+v", c)
329		}
330	}
331	
332	// TestOpenRestoresDestroyedLeafWithoutChildren 没有分出子样时销毁量等于
333	// 初始量即可正常恢复。
334	func TestOpenRestoresDestroyedLeafWithoutChildren(t *testing.T) {
335		l := &ledger{
336			Samples: map[string]*sampleRecord{
337				"LEAF": destroyedSample("LEAF", 5000, 0, 5000),
338			},
339		}
340		path := writeStructLedger(t, l)
341		s, err := Open(path)
342		if err != nil {
343			t.Fatalf("无子样且销毁量等于初始量应正常恢复: %v", err)
344		}
345		got, err := s.GetSample("LEAF")
346		if err != nil {
347			t.Fatal(err)
348		}
349		if got.InitialQty != "5.000" || got.Remaining != "0.000" ||
350			got.Destruction == nil || got.Destruction.Qty != "5.000" {
351			t.Fatalf("销毁信息恢复错误: %+v", got)
352		}
353	}
354	
355	// TestOpenDestroyedAccountingUsesChildInitialOnly 核对只取各直接子样创建
356	// 时的初始量：
357	//   - 孙样不重复计入：父样分出 4.000 给子样，子样又把 4.000 全部分给孙样，
358	//     父样销毁 6.000 仍满足 6.000 + 4.000 = 10.000；
359	//   - 子样后来继续分装、转交或销毁不改变父样已分出的量：子样当前只剩
360	//     2.250（自身又分出 1.000）或已全部销毁，父样仍按子样初始量 3.250 核
361	//     对，不能改用子样当前剩余量。
362	func TestOpenDestroyedAccountingUsesChildInitialOnly(t *testing.T) {
363		// 场景一：孙样不重复计入；子样分装用尽（无销毁信息）也合法。
364		grandchild := plainChild("G", "C", 4000, 4000)
365		childExhausted := plainChild("C", "P", 4000, 0)
366		childExhausted.Children = []string{"G"}
367		childExhausted.History = append(childExhausted.History, historyRecord{
368			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
369		})
370		l1 := &ledger{
371			Samples: map[string]*sampleRecord{
372				"P": destroyedSample("P", 10000, 0, 6000, "C"),
373				"C": childExhausted,
374				"G": grandchild,
375			},
376		}
377		if s, err := Open(writeStructLedger(t, l1)); err != nil {
378			t.Fatalf("孙样不得计入父样销毁核对，6.000+4.000=10.000 应恢复: %v", err)
379		} else {
380			p, _ := s.GetSample("P")
381			if p.Destruction == nil || p.Destruction.Qty != "6.000" {
382				t.Fatalf("父样销毁量恢复错误: %+v", p.Destruction)
383			}
384		}
385	
386		// 场景二：子样自己又分出 1.000，当前只剩 2.250；父样仍按子样初始量
387		// 3.250 核对（6.750 + 3.250 = 10.000）。
388		childSplit := plainChild("S-001-A", "S-001", 3250, 2250)
389		childSplit.Children = []string{"S-001-A-G"}
390		childSplit.History = append(childSplit.History, historyRecord{
391			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
392		})
393		l2 := &ledger{
394			Samples: map[string]*sampleRecord{
395				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
396				"S-001-A":   childSplit,
397				"S-001-A-G": plainChild("S-001-A-G", "S-001-A", 1000, 1000),
398			},
399		}
400		if _, err := Open(writeStructLedger(t, l2)); err != nil {
401			t.Fatalf("必须按子样创建时初始量 3.250 核对，不能用其当前剩余 2.250: %v", err)
402		}
403	
404		// 场景三：子样已独立销毁（销毁量取其当时剩余 2.250），父样核对仍按
405		// 子样初始量 3.250；父子销毁记录恢复后各自独立。
406		childDestroyed := destroyedSampleWithParent("S-001-A", "S-001", 3250, 2250)
407		childDestroyed.Children = []string{"S-001-A-G"}
408		grand := plainChild("S-001-A-G", "S-001-A", 1000, 1000)
409		l3 := &ledger{
410			Samples: map[string]*sampleRecord{
411				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
412				"S-001-A":   childDestroyed,
413				"S-001-A-G": grand,
414			},
415		}
416		s3, err := Open(writeStructLedger(t, l3))
417		if err != nil {
418			t.Fatalf("子样后来销毁不改变父样已分出量，文件应正常恢复: %v", err)
419		}
420		parent, _ := s3.GetSample("S-001")
421		child, _ := s3.GetSample("S-001-A")
422		if parent.Destruction == nil || parent.Destruction.Qty != "6.750" {
423			t.Fatalf("父样销毁量应为 6.750: %+v", parent.Destruction)
424		}
425		if child.Destruction == nil || child.Destruction.Qty != "2.250" || child.Remaining != "0.000" {
426			t.Fatalf("子样销毁记录应独立保留为 2.250: %+v", child.Destruction)
427		}
428	}
429	
430	// destroyedSampleWithParent 构造一份有来源、带销毁信息的子样记录。
431	func destroyedSampleWithParent(id, parent string, initial, destroyedQty int64) *sampleRecord {
432		s := destroyedSample(id, initial, 0, destroyedQty)
433		s.ParentID = parent
434		return s
435	}
436	
437	// TestOpenDestroyedAccountingIndependentAcrossRoots 同一份数据里的其他原样
438	// 不参与某次核对：原样 A 的销毁等式不成立时，即使原样 B 的记录完全正常，
439	// 也不能拿 B 的数量去凑 A 的差额（整份文件仍失败）；反之各自守恒时互不
440	// 影响、正常恢复。
441	func TestOpenDestroyedAccountingIndependentAcrossRoots(t *testing.T) {
442		// 各自守恒：A=10.000 分出 3.250 销毁 6.750；B=5.000 全部销毁。
443		good := &ledger{
444			Samples: map[string]*sampleRecord{
445				"A":   destroyedSample("A", 10000, 0, 6750, "A-C"),
446				"A-C": plainChild("A-C", "A", 3250, 3250),
447				"B":   destroyedSample("B", 5000, 0, 5000),
448			},
449		}
450		s, err := Open(writeStructLedger(t, good))
451		if err != nil {
452			t.Fatalf("两份原样各自守恒应正常恢复: %v", err)
453		}
454		a, _ := s.GetSample("A")
455		b, _ := s.GetSample("B")
456		if a.Destruction == nil || a.Destruction.Qty != "6.750" {
457			t.Fatalf("原样 A 销毁量错误: %+v", a.Destruction)
458		}
459		if b.Destruction == nil || b.Destruction.Qty != "5.000" {
460			t.Fatalf("原样 B 销毁量错误: %+v", b.Destruction)
461		}
462	
463		// A 的销毁量被错写成 10.000（多 3.250），不能用 B 的任何数量抵消。
464		bad := &ledger{
465			Samples: map[string]*sampleRecord{
466				"A":   destroyedSample("A", 10000, 0, 10000, "A-C"),
467				"A-C": plainChild("A-C", "A", 3250, 3250),
468				"B":   destroyedSample("B", 5000, 0, 5000),
469			},
470		}
471		mustRejectOpen(t, writeStructLedger(t, bad), "A", "10.000", "3.250")
472	}
473	
474	// TestOpenDestroyedAtLargeBounds 大数量边界：支持上限附近的合法销毁记录
475	// 必须逐位准确恢复；销毁量与直接子样初始量合计超出 int64 支持范围时按
476	// 无效数据拒绝，不能因数量过大忽略差额或接受回绕后的错误等式。
477	func TestOpenDestroyedAtLargeBounds(t *testing.T) {
478		const (
479			maxUnits   int64 = 9223372036854775807 // 9223372036854775.807 毫升
480			belowUnits int64 = 9223372036854775806 // 9223372036854775.806 毫升
481		)
482	
483		// 合法：初始量取上限，分出上限-0.001 的直接子样，销毁最后的 0.001，
484		// 合计恰好等于上限，重开后三位小数逐位一致。
485		legal := &ledger{
486			Samples: map[string]*sampleRecord{
487				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "BIG-C"),
488				"BIG-C": func() *sampleRecord {
489					c := plainChild("BIG-C", "BIG", belowUnits, belowUnits)
490					return c
491				}(),
492			},
493		}
494		s, err := Open(writeStructLedger(t, legal))
495		if err != nil {
496			t.Fatalf("上限附近的合法销毁记录应准确恢复: %v", err)
497		}
498		big, _ := s.GetSample("BIG")
499		if big.InitialQty != maxQtyString || big.Remaining != "0.000" ||
500			big.Destruction == nil || big.Destruction.Qty != "0.001" {
501			t.Fatalf("上限父样恢复不精确: %+v", big)
502		}
503		bigC, _ := s.GetSample("BIG-C")
504		if bigC.InitialQty != belowMaxString || bigC.Remaining != belowMaxString {
505			t.Fatalf("上限附近子样恢复不精确: init=%s remaining=%s",
506				bigC.InitialQty, bigC.Remaining)
507		}
508	
509		// 溢出场景一：销毁量 + 直接子样初始量在上限之外一个最小刻度
510		//（子样 上限-0.001，销毁 0.002：合计 上限+0.001），最终求和溢出，
511		// 必须按超出支持范围拒绝。
512		overflowFinal := &ledger{
513			Samples: map[string]*sampleRecord{
514				"BIG":   destroyedSample("BIG", maxUnits, 0, 2, "BIG-C"),
515				"BIG-C": plainChild("BIG-C", "BIG", belowUnits, belowUnits),
516			},
517		}
518		mustRejectOpen(t, writeStructLedger(t, overflowFinal), "BIG", "超出可表示范围")
519	
520		// 溢出场景二：各直接子样初始量累加本身溢出（子样合计超过上限），
521		// 在统计直接子样总量时即拒绝，不能回绕成一个小数量再去凑等式。
522		overflowChildren := &ledger{
523			Samples: map[string]*sampleRecord{
524				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "C1", "C2"),
525				"C1":  plainChild("C1", "BIG", belowUnits, belowUnits),
526				"C2":  plainChild("C2", "BIG", 2, 2),
527			},
528		}
529		mustRejectOpen(t, writeStructLedger(t, overflowChildren), "BIG", "超出可表示范围")
530	}
531	
532	// TestOpenLegacySamplesWithoutDestructionUnaffected 没有销毁信息的旧样品
533	// 继续按现有规则恢复：无论剩余量是否为零都不参与销毁数量核对，也不能据
534	// 剩余量为零补出销毁记录。
535	func TestOpenLegacySamplesWithoutDestructionUnaffected(t *testing.T) {
536		// 旧样品分装用尽、剩余量为零、无销毁信息；另带一个正常有量旧样品。
537		exhausted := plainChild("OLD", "", 10000, 0)
538		exhausted.ParentID = ""
539		exhausted.Children = []string{"OLD-C"}
540		exhausted.History = []historyRecord{{
541			Kind: "register", Time: registerCheckAt, Holder: "h", Location: "l",
542		}, {
543			Kind: "split", Time: splitCheckAt, Holder: "h", Location: "l",
544		}}
545		exhausted.Holder, exhausted.Location = "h", "l"
546		child := plainChild("OLD-C", "OLD", 10000, 10000)
547		fresh := &sampleRecord{
548			ID: "NEW", Initial: 5000, Remaining: 5000, Holder: "h", Location: "l",
549			Children: []string{},
550			History: []historyRecord{{
551				Kind: "register", Time: registerCheckAt, Holder: "h", Location: "l",
552			}},
553		}
554		l := &ledger{
555			Samples: map[string]*sampleRecord{
556				"OLD":   exhausted,
557				"OLD-C": child,
558				"NEW":   fresh,
559			},
560		}
561		s, err := Open(writeStructLedger(t, l))
562		if err != nil {
563			t.Fatalf("无销毁信息的旧样品应按原规则恢复，不做销毁数量核对: %v", err)
564		}
565		old, _ := s.GetSample("OLD")
566		if old.Remaining != "0.000" || old.Destruction != nil {
567			t.Fatalf("旧样品剩余为零也不能补出销毁记录: %+v", old)
568		}
569		newSample, _ := s.GetSample("NEW")
570		if newSample.Destruction != nil || newSample.Remaining != "5.000" {
571			t.Fatalf("正常旧样品不应受新核对影响: %+v", newSample)
572		}
573	}
574	
575	// TestOpenRestoresParentAndChildDestructionViaAPI 端到端：通过公开操作产生
576	// 父子各自销毁的合法文件，重开后两份销毁记录独立保留，来源、人员、地点、
577	// 保管历史与销毁量都可查询，且恢复后操作限制与幂等行为保持兼容。
578	func TestOpenRestoresParentAndChildDestructionViaAPI(t *testing.T) {
579		dir := t.TempDir()
580		path := filepath.Join(dir, "data.json")
581		s, err := Open(path)
582		if err != nil {
583			t.Fatal(err)
584		}
585		s.now = func() time.Time { return registerCheckAt }
586		mustRegister(t, s, "P", "10.000", "张三", "A")
587		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
588			{ID: "C", Qty: "3.250"},
589		}}); err != nil {
590			t.Fatal(err)
591		}
592		parentAt := time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
593		if _, err := s.Destroy(DestroyInput{
594			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
595		}); err != nil {
596			t.Fatalf("销毁父样剩余 6.750: %v", err)
597		}
598		childAt := parentAt.Add(time.Hour)
599		if _, err := s.Destroy(DestroyInput{
600			SampleID: "C", Operator: "张三", Location: "A", At: childAt, Reason: "子样销毁",
601		}); err != nil {
602			t.Fatalf("销毁子样全部 3.250: %v", err)
603		}
604	
605		s2, err := Open(path)
606		if err != nil {
607			t.Fatalf("父子各自销毁的合法文件应正常恢复: %v", err)
608		}
609		p, err := s2.GetSample("P")
610		if err != nil {
611			t.Fatal(err)
612		}
613		c, err := s2.GetSample("C")
614		if err != nil {
615			t.Fatal(err)
616		}
617		if p.InitialQty != "10.000" || p.Remaining != "0.000" ||
618			p.Destruction == nil || p.Destruction.Qty != "6.750" ||
619			p.Destruction.Operator != "张三" || p.Destruction.Location != "A" ||
620			p.Destruction.Reason != "原样销毁" || !p.Destruction.At.Equal(parentAt) {
621			t.Fatalf("父样销毁记录恢复错误: %+v", p)
622		}
623		if len(p.Children) != 1 || p.Children[0] != "C" {
624			t.Fatalf("父样来源/子样关系应保留: %+v", p.Children)
625		}
626		if c.ParentID != "P" || c.InitialQty != "3.250" || c.Remaining != "0.000" ||
627			c.Destruction == nil || c.Destruction.Qty != "3.250" ||
628			c.Destruction.Reason != "子样销毁" || !c.Destruction.At.Equal(childAt) {
629			t.Fatalf("子样销毁记录恢复错误: %+v", c)
630		}
631	
632		// 恢复后销毁幂等与操作限制继续生效。
633		if _, err := s2.Destroy(DestroyInput{
634			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
635		}); err != nil {
636			t.Fatalf("恢复后相同销毁请求应幂等返回: %v", err)
637		}
638		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "X", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
639			t.Fatalf("恢复后已销毁父样仍不得分装, got %v", err)
640		}
641		if _, err := s2.Handover(HandoverInput{
642			TransferID: "T-X", SampleID: "C",
643			FromHolder: "张三", FromLocation: "A",
644			ToHolder: "李四", ToLocation: "B", HandedOverAt: childAt.Add(time.Hour),
645		}); !errors.Is(err, ErrConflict) {
646			t.Fatalf("恢复后已销毁子样仍不得发起交接, got %v", err)
647		}
648	
649		// 原始文件没有被恢复流程改写（仍为最后一次成功操作落盘的内容，
650		// 重新打开前后再次读取一致）。
651		raw, err := os.ReadFile(path)
652		if err != nil {
653			t.Fatal(err)
654		}
655		if !strings.Contains(string(raw), `"qty": 6750`) || !strings.Contains(string(raw), `"qty": 3250`) {
656			t.Fatalf("落盘文件应原样保留两份销毁量: %s", string(raw))
657		}
658	}
