353			t.Fatalf("销毁父样不能改变已分出的子样: %+v", c)
354		}
355	
356		// 子样仍可独立流转并销毁；销毁子样不再扣减父样。
357		c2, err := s.Handover(HandoverInput{
358			TransferID: "TC", SampleID: "C",
359			FromHolder: "张三", FromLocation: "A",
360			ToHolder: "李四", ToLocation: "B", HandedOverAt: at.Add(time.Hour),
361		})
362		if err != nil {
363			t.Fatalf("未销毁子样应能继续交接: %v", err)
364		}
365		if c2.Confirmed {
366			t.Fatalf("子样交接应处于待确认")
367		}
368		if _, err := s.Confirm(ConfirmInput{"TC", "李四", "B", at.Add(2 * time.Hour)}); err != nil {
369			t.Fatal(err)
370		}
371		cd, err := s.Destroy(DestroyInput{
372			SampleID: "C", Operator: "李四", Location: "B",
373			At: at.Add(3 * time.Hour), Reason: "用尽销毁",
374		})
375		if err != nil {
376			t.Fatalf("destroy child: %v", err)
377		}
378		if cd.Destruction.Qty != "4.000" || cd.Remaining != "0.000" {
379			t.Fatalf("子样销毁视图错误: %+v", cd)
380		}
381		p2, _ := s.GetSample("P")
382		if p2.Remaining != "0.000" || p2.Destruction == nil || p2.Destruction.Qty != "6.000" {
383			t.Fatalf("销毁子样不得再扣减父样: %+v", p2)
384		}
385	}
386	
387	// TestDestroyPersistsAcrossReopen 重开后销毁信息、剩余量、操作限制与
388	// 幂等判断继续有效。
389	func TestDestroyPersistsAcrossReopen(t *testing.T) {
390		dir := t.TempDir()
