418		}
419		if got.Destruction == nil || got.Destruction.Operator != "张三" ||
420			got.Destruction.Location != "A" || got.Destruction.Reason != "污染" ||
421			got.Destruction.Qty != "3.125" || !got.Destruction.At.Equal(at) {
422			t.Fatalf("重开后销毁信息应保留: %+v", got.Destruction)
423		}
424		if len(got.History) != len(first.History) ||
425			got.History[len(got.History)-1].Kind != "destroy" {
426			t.Fatalf("重开后销毁历史应保留: %+v", got.History)
427		}
428	
429		// 重开后重复提交相同信息仍幂等。
430		again, err := s2.Destroy(DestroyInput{
431			SampleID: "P", Operator: " 张三 ", Location: "A", At: at, Reason: "污染",
432		})
433		if err != nil {
