480		}
481		raw, err := json.MarshalIndent(&legacy, "", "  ")
482		if err != nil {
483			t.Fatal(err)
484		}
485		if err := os.WriteFile(path, raw, 0o600); err != nil {
486			t.Fatal(err)
487		}
488	
489		s, err := Open(path)
490		if err != nil {
491			t.Fatal(err)
492		}
493		got, err := s.GetSample("OLD")
494		if err != nil {
495			t.Fatal(err)
496		}
497		if got.Remaining != "0.000" {
